<?php require_once __DIR__.'/functions.php'; $rooms=db()->query("SELECT * FROM rooms WHERE status='active' ORDER BY id")->fetchAll(); $selected=(int)($_GET['room']??0); if($_SERVER['REQUEST_METHOD']==='POST'){ $room=(int)$_POST['room_id'];$in=$_POST['check_in'];$out=$_POST['check_out'];$guests=max(1,(int)$_POST['guests']);$name=trim($_POST['guest_name']);$phone=trim($_POST['phone']);$notes=trim($_POST['notes']); if($out<=$in){flash('Check-out must be after check-in.','danger');}else{ $s=db()->prepare("SELECT COUNT(*) FROM bookings WHERE room_id=? AND status IN ('pending','confirmed') AND check_in < ? AND check_out > ?");$s->execute([$room,$out,$in]); if($s->fetchColumn()>0){flash('That room is already booked for those dates. Please choose another room or dates.','danger');}else{ $s=db()->prepare('SELECT price FROM rooms WHERE id=? AND status="active"');$s->execute([$room]);$price=$s->fetchColumn();$days=(new DateTime($in))->diff(new DateTime($out))->days;$total=$price*$days;$uid=$_SESSION['user']['id']??null;$s=db()->prepare('INSERT INTO bookings(user_id,room_id,check_in,check_out,guests,total,guest_name,phone,notes) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$uid,$room,$in,$out,$guests,$total,$name,$phone,$notes]);flash('Booking request submitted successfully. Reception will confirm your reservation.');redirect(logged()?'my-bookings.php':'booking.php'); }}} header_html('Book a Room'); ?><main class="container py-5" style="max-width:850px"><h1 class="display-6 fw-bold">Book your room</h1><p class="text-secondary">Your dates are checked against current bookings before the request is saved.</p><div class="card shadow-sm"><div class="card-body p-4"><form method="post" class="row g-3"><input type="hidden" name="room_id" value="<?=$selected?>"><div class="col-md-6"><label class="form-label">Room</label><select name="room_id" class="form-select" required><?php foreach($rooms as $r):?><option value="<?=$r['id']?>" <?=$selected==$r['id']?'selected':''?>><?=e($r['name'])?> — TZS <?=number_format($r['price'])?>/night</option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Check-in</label><input type="date" name="check_in" class="form-control" required min="<?=date('Y-m-d')?>"></div><div class="col-md-3"><label class="form-label">Check-out</label><input type="date" name="check_out" class="form-control" required></div><div class="col-md-3"><label class="form-label">Guests</label><input type="number" name="guests" class="form-control" value="1" min="1" max="10" required></div><div class="col-md-9"><label class="form-label">Full name</label><input name="guest_name" class="form-control" value="<?=e($_SESSION['user']['name']??'')?>" required></div><div class="col-md-6"><label class="form-label">Phone</label><input name="phone" class="form-control" placeholder="+255 7XX XXX XXX" required></div><div class="col-12"><label class="form-label">Notes</label><textarea name="notes" class="form-control" rows="3" placeholder="Arrival time or special requests"></textarea></div><div class="col-12"><button class="btn btn-gold btn-lg">Submit booking request</button></div></form></div></div></main><?php footer_html(); ?>